# -*- coding: utf-8 -*-
import io,os,sys,base64,json
BASE=sys.argv[1] if len(sys.argv)>1 else "."
SRV=os.path.join(BASE,"server_container.mjs"); CLI=os.path.join(BASE,"shells","ik.html")
Sp=json.loads(base64.b64decode("").decode()); Cp=json.loads(base64.b64decode("").decode())
def apply(path,pairs,label):
    s=io.open(path,encoding="utf-8").read()
    for o64,n64 in pairs:
        o=base64.b64decode(o64).decode(); n=base64.b64decode(n64).decode()
        if n in s and o not in s: continue
        c=s.count(o); assert c==1, label+" anchor=%d :: %s"%(c,o[:40])
        s=s.replace(o,n,1)
    if not os.path.exists(path+".v3bak"): io.open(path+".v3bak","w",encoding="utf-8").write(io.open(path,encoding="utf-8").read())
    io.open(path,"w",encoding="utf-8").write(s); print("OK",label)
apply(SRV,Sp,"server"); apply(CLI,Cp,"client"); print("V3 incremental TAMAM")
